    if (!key || !keyring) {
        return -EINVAL;
    }

    if (key->type->v1.instantiate) {
        return -EPERM;
    }

    if (key->flags & 1 << 2) {
        return -EEXIST;
    }

    key->flags |= 1 << 4;
    key->expiry = jiffies + timeout * HZ;
    key->payload.error = error;

    if (keyring) {
        if (key_add_link(keyring, key, NULL)) {
            return -ENOMEM;
        }
    }

    key->flags |= 1 << 1;
    key->flags &= ~(1 << 0);

    if (authkey) {
        key_revoke(authkey);
    }

    key_schedule_gc(key->expiry);
    wake_up_bit(&key->wait_keyring, 0);

    return 0;
}

