int key_reject_and_link(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    int ret = 0;

    if (!key || (keyring && !keyring)) {
        return -EINVAL;
    }

    down_write(&key->sem);
    if (key->type->reject) {
        ret = key->type->reject(key, error);
        if (ret < 0) {
            up_write(&key->sem);
            return ret;
        }
    }

    key->flags |= 1 << (KEY_FLAG_NEGATIVE - 1);
    key->expiry = get_seconds() + timeout;
    key_schedule_gc(key->expiry);

    if (keyring) {
        ret = key_link(keyring, key);
        if (ret < 0) {
            up_write(&key->sem);
            return ret;
        }

        key_invalidate(authkey);
    }

    up_write(&key->sem);

    if (key->type->construct) {
        wake_up_key(key);
    }

    return ret;
}

int reject_key_and_link(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    int ret = 0;

    if (!key || !keyring) {
        return -EINVAL;
    }

    /* Ensure the key is not already instantiated */
    if (key->type->instructions[KI_INSTANTIATE]) {
        return -EEXIST;
    }

    /* Mark the key as negatively instantiated with the specified error code */
    key->description = "rejected";
    key->type = key_type_negative;
    key->perm |= KEY_POS_ALL | KEY_USR_ALL;
    key->timeout = jiffies + timeout * HZ;
    key->error = error;

    /* Schedule garbage collection for the key */
    schedule_key_gc(key);

    /* If keyring is provided, link the key to the keyring */
    if (keyring) {
        ret = key_link(keyring, key);
        if (ret < 0) {
            return ret;
        }

        /* If authkey is provided, revoke it */
        if (authkey) {
            key_revoke(authkey);
        }
    }

    /* Wake up any waiting processes if the key was constructed */
    wake_up_key_waiters(key);

    return 0;
}

int reject_key_and_link_to_keyring(struct key *key, unsigned timeout, unsigned error, struct key *keyring, struct key *authkey) {
    if (!key || !keyring) {
        return -EINVAL;
    }

    if (key->instanced) {
        return -EEXIST;
    }

    key->negative = 1;
    key->expiry = get_current_time() + timeout;
    schedule_gc();

    int result = link_key_to_keyring(key, keyring);
    if (result < 0) {
        return result;
    }

    if (authkey) {
        revoke_key(authkey);
    }

    if (key->constructed) {
        wake_up_waiting_processes(key);
    }

    return 0;
}
